// Normalize lead payload from either Website Webhook POST or Gmail Trigger
const raw = $input.first().json;
const body = raw.body || raw;

// Parse email text if triggered via Gmail
const emailText = raw.text || raw.snippet || '';
function extractFromEmail(label) {
  const regex = new RegExp(label + '\\s*[:\\-]?\\s*(.+)', 'i');
  const match = emailText.match(regex);
  return match ? match[1].trim() : '';
}

const fullName = body.full_name || body.fullName || body.name || extractFromEmail('Full Name') || 'Valued Client';
const email = body.email || body.work_email || extractFromEmail('Email') || '';
let phone = (body.phone || body.whatsapp || body.whatsapp_number || extractFromEmail('Phone|WhatsApp') || '').replace(/[^+\d]/g, '');
if (phone && !phone.startsWith('+')) {
  phone = '+' + phone;
}

const servicesRaw = body.services || body.service || body.i_need_help_with || extractFromEmail('Services Required|I Need Help With') || 'n8n Automation';
const primaryService = Array.isArray(servicesRaw) ? servicesRaw[0] : String(servicesRaw).split(',')[0].trim();
const allServices = Array.isArray(servicesRaw) ? servicesRaw.join(', ') : String(servicesRaw);
const projectBrief = body.project_brief || body.brief || body.message || extractFromEmail('Project / Advisory Brief') || 'Requested a 30-minute strategy call via ismylmohammad.com.';
const sourceChannel = raw.headers ? 'website_webhook' : 'gmail_parser';

// Map E.164 prefix to Timezone & Region (Primary hubs: USA, Canada, India, Australia + UK/GCC/EU/APAC)
const prefixMap = [
  { prefix: '+91', tz: 'Asia/Kolkata', offsetHours: 5.5, region: 'India' },
  { prefix: '+61', tz: 'Australia/Sydney', offsetHours: 10.0, region: 'Australia' },
  { prefix: '+64', tz: 'Pacific/Auckland', offsetHours: 12.0, region: 'New Zealand' },
  { prefix: '+65', tz: 'Asia/Singapore', offsetHours: 8.0, region: 'Singapore' },
  { prefix: '+971', tz: 'Asia/Dubai', offsetHours: 4.0, region: 'UAE' },
  { prefix: '+966', tz: 'Asia/Riyadh', offsetHours: 3.0, region: 'Saudi Arabia' },
  { prefix: '+974', tz: 'Asia/Qatar', offsetHours: 3.0, region: 'Qatar' },
  { prefix: '+44', tz: 'Europe/London', offsetHours: 0.0, region: 'United Kingdom' },
  { prefix: '+49', tz: 'Europe/Berlin', offsetHours: 1.0, region: 'Germany' },
  { prefix: '+33', tz: 'Europe/Paris', offsetHours: 1.0, region: 'France' },
  { prefix: '+31', tz: 'Europe/Amsterdam', offsetHours: 1.0, region: 'Netherlands' },
  { prefix: '+1', tz: 'America/New_York', offsetHours: -5.0, region: 'USA / Canada' }
];

let matchedTz = { prefix: '+91', tz: 'Asia/Kolkata', offsetHours: 5.5, region: 'India (Default)' };
for (const item of prefixMap) {
  if (phone.startsWith(item.prefix)) {
    matchedTz = item;
    break;
  }
}

// Compute Safe Calling Window (9:00 AM - 7:00 PM Lead Local Time, plus minimum 3-minute warm delay)
const nowUtcMs = Date.now();
const leadLocalMs = nowUtcMs + matchedTz.offsetHours * 3600 * 1000;
const leadLocalDate = new Date(leadLocalMs);
const localHour = leadLocalDate.getUTCHours();

let scheduledUtcMs = nowUtcMs + 3 * 60 * 1000; // Default: 3-minute delay after form submission
let windowStatus = 'WITHIN_BUSINESS_HOURS_3MIN_DELAY';

if (localHour < 9) {
  // Schedule for 9:15 AM local time today
  const hoursUntil9 = 9 - localHour;
  scheduledUtcMs = nowUtcMs + (hoursUntil9 * 3600 * 1000) + (15 * 60 * 1000);
  windowStatus = 'DELAYED_UNTIL_9AM_LOCAL';
} else if (localHour >= 19) {
  // Schedule for 9:15 AM local time tomorrow
  const hoursUntilNext9 = (24 - localHour) + 9;
  scheduledUtcMs = nowUtcMs + (hoursUntilNext9 * 3600 * 1000) + (15 * 60 * 1000);
  windowStatus = 'DELAYED_UNTIL_NEXT_DAY_9AM_LOCAL';
}

// Pillar-specific discovery question bank for Vapi assistantOverrides
const pillarQuestions = {
  'n8n Automation': 'Ask which manual workflows, webhooks, or APIs they want to orchestrate in n8n, their approximate daily event volume, and whether they run self-hosted or cloud n8n.',
  'AI & Data Governance': 'Ask which regulatory or assurance frameworks they are targeting (such as ISO/IEC 42001, NIST AI RMF, or EU AI Act) and how many AI models or pipelines are in production.',
  'Data Engineering': 'Ask about their current data stack (e.g., PostgreSQL, Databricks, Snowflake), ETL bottlenecks, and data lineage or catalog needs.',
  'Data Analysis': 'Ask about their primary data sources, executive reporting or KPI goals, and current analytics tooling.',
  'Agentic AI & RAG': 'Ask about their knowledge sources, vector database setup (e.g., pgvector, Pinecone, Databricks), latency requirements, and hallucination guardrails.',
  'Enterprise Architecture': 'Ask about their current cloud infrastructure, multi-system integration challenges, and reliability or compliance SLAs.',
  'Consulting & Advisory': 'Ask whether they are looking for a C-suite roadmap, architecture audit, or ongoing fractional advisory with Ismyl.',
  'Web & Custom Tech': 'Ask about the custom web application or API platform they are building, expected user scale, and target launch window.'
};

const tailoredDiscoveryDirective = pillarQuestions[primaryService] || pillarQuestions['n8n Automation'];
const leadId = 'LEAD-' + Date.now() + '-' + Math.random().toString(36).substring(2, 7).toUpperCase();

return [{
  json: {
    lead_id: leadId,
    full_name: fullName,
    email: email,
    phone: phone,
    primary_service: primaryService,
    all_services: allServices,
    project_brief: projectBrief,
    source_channel: sourceChannel,
    region: matchedTz.region,
    timezone: matchedTz.tz,
    window_status: windowStatus,
    scheduled_call_iso: new Date(scheduledUtcMs).toISOString(),
    tailored_discovery_directive: tailoredDiscoveryDirective,
    retry_count: 0,
    created_at_iso: new Date(nowUtcMs).toISOString()
  }
}];

