parameters.jsCode:
const crypto = require('crypto');
const body = $input.first().json.body || $input.first().json;
const msg = body.message || body;
const call = msg.call || {};
const vars = call.assistantOverrides?.variableValues || {};
const analysis = msg.analysis || {};
const structured = analysis.structuredData || {};

const endedReason = msg.endedReason || call.endedReason || 'completed';
const transcript = msg.transcript || '';
const summary = analysis.summary || msg.summary || 'No summary generated.';
const recordingUrl = msg.recordingUrl || call.recordingUrl || '';

// Check if call was answered vs missed
const missedReasons = ['customer-did-not-answer', 'customer-busy', 'voicemail', 'twilio-failed-to-connect-call'];
const isAnswered = !missedReasons.includes(endedReason) && transcript.length > 30;

// Generate cryptographic SHA-256 provenance digest for audit trail
const provenancePayload = JSON.stringify({
  lead_id: vars.lead_id || '',
  phone: vars.phone || call.customer?.number || '',
  ended_reason: endedReason,
  transcript: transcript,
  timestamp: new Date().toISOString()
});
const sha256Hash = crypto.createHash('sha256').update(provenancePayload).digest('hex');

const currentRetry = Number(vars.retry_count || 0);
const nextRetryHours = Math.pow(2, currentRetry + 1); // Exponential backoff: 2h, 4h, 8h
const nextRetryIso = new Date(Date.now() + nextRetryHours * 3600 * 1000).toISOString();

return [{
  json: {
    lead_id: vars.lead_id || 'UNKNOWN',
    full_name: vars.full_name || call.customer?.name || 'Client',
    email: vars.email || '',
    phone: vars.phone || call.customer?.number || '',
    primary_service: vars.primary_service || 'n8n Automation',
    ended_reason: endedReason,
    is_answered: isAnswered,
    summary: summary,
    transcript: transcript,
    recording_url: recordingUrl,
    qualified_scope: structured.scope_summary || 'Discussed on call',
    qualified_timeline: structured.timeline || 'TBD',
    qualified_budget: structured.budget_range || 'TBD',
    meeting_booked: Boolean(structured.meeting_booked),
    sha256_provenance: sha256Hash,
    retry_count: currentRetry + 1,
    next_retry_iso: nextRetryIso
  }
}];

